<h2>בקרת פרסום</h2><p><?=networkEnabled()?'פרסומים חדשים פעילים':'פרסומים חדשים מושהים — צפייה ושמירה ממשיכות לפעול'?></p><form method="post"><?=csrf()?><input type="hidden" name="kind" value="settings"><input type="hidden" name="id" value="publishing"><button name="decision" value="<?=networkEnabled()?'pause':'resume'?>"><?=networkEnabled()?'השהיית פרסומים חדשים':'חידוש פרסומים חדשים'?></button></form>
<h2>ערעורים ובקשות לבדיקה חוזרת</h2><?php foreach(socialQuery("SELECT * FROM network_appeals WHERE state='pending' ORDER BY created LIMIT 100") as $appeal):?><article class="social-card"><h3><?=e($appeal['kind'].' · '.$appeal['target'])?></h3><p><?=nl2br(e($appeal['body']))?></p><p>בדקו את ההחלטה המקורית ביומן. סגירת ערעור אינה מפרסמת תוכן; יש לאשר אותו בנפרד לאחר הבדיקה.</p><form method="post"><?=csrf()?><input type="hidden" name="expected_version" value="<?=e(networkReviewVersion('appeal',(string)$appeal['id']))?>"><input type="hidden" name="kind" value="appeal"><input type="hidden" name="id" value="<?=(int)$appeal['id']?>"><label>הסבר למחבר<textarea name="moderator_note" minlength="10" maxlength="500" required></textarea></label><button name="decision" value="resolve">טופל</button><button name="decision" value="reject">ההחלטה נשארת</button></form></article><?php endforeach?>
<h2>גרסאות לשוניות ותיקונים לבדיקה</h2><?php foreach(socialQuery("SELECT * FROM network_submissions WHERE state='pending' ORDER BY created LIMIT 100") as $translation):$text=json_decode($translation['document'],true);?><article class="social-card" data-review-pending><h3><?=e($text['public_title']??$text['title']??'')?></h3><p><?=e($translation['kind'])?> · <?=e($translation['language'])?> · גרסת מקור <?=(int)$translation['base_version']?></p><p dir="auto"><?=nl2br(e($text['body']??$text['summary']??$text['description']??''))?></p><?php socialAdminActions('translation',$translation['id']);?></article><?php endforeach?>
<h2>פרסומים בקהילה</h2>
<?php foreach(socialQuery("SELECT p.*,m.handle,l.language,l.document,l.state review_state FROM network_posts p JOIN members m ON m.id=p.owner JOIN network_localizations l ON l.kind='post' AND l.target=p.id WHERE ".($history?"p.state!='removed'":"p.state='pending'")." ORDER BY (p.state='pending') DESC,p.created DESC LIMIT 100") as $post):$doc=json_decode($post['document'],true);?>
<article class="social-card" <?=$post['state']==='pending'?'data-review-pending':''?>><h3><?=e($doc['title'])?></h3><p>@<?=e($post['handle'])?> · <?=e($post['kind'])?> · <?=e($post['language'])?> · <?=e($post['review_state'])?></p><p dir="auto"><?=nl2br(e($doc['body']))?></p><p><?=e($doc['city'])?> · <?=e($doc['visited_at']??'')?> · <?=e($doc['source']??'')?></p><?php if(!empty($doc['commercial'])):?><strong>קשר מסחרי מוצהר</strong><?php endif?><?php foreach($doc['photos']??[] as $photo):?><img src="/community/media/<?=e($photo)?>/" width="250" alt="תמונה לבדיקה"><?php endforeach?><?php socialAdminActions('post',$post['id']);?></article><?php endforeach?>
<h2>תגובות לבדיקה</h2><?php foreach(socialQuery("SELECT c.*,m.handle FROM network_comments c JOIN members m ON m.id=c.owner WHERE c.state='pending' ORDER BY c.created LIMIT 100") as $comment):?><article class="social-card" data-review-pending><p>@<?=e($comment['handle'])?> · <?=e($comment['language'])?></p><p dir="auto"><?=nl2br(e($comment['body']))?></p><a href="<?=e(networkUrl($comment['kind'],$comment['target']))?>"><?=e(uiMessage('admin.release.61'))?></a><?php socialAdminActions('comment',$comment['id']);?></article><?php endforeach?>
