<h2>יומן החלטות אחרונות</h2><table><thead><tr><th>זמן UTC</th><th>מנהל</th><th>סוג</th><th>מזהה</th><th>פעולה</th></tr></thead><tbody><?php foreach(socialQuery('SELECT * FROM member_moderation ORDER BY id DESC LIMIT 100') as $decision):?><tr><td><?=gmdate('Y-m-d H:i',$decision['created'])?></td><td><?=(int)$decision['admin_id']?></td><td><?=e($decision['kind'])?></td><td><?=e($decision['target'])?></td><td><?=e($decision['action'])?></td></tr><?php endforeach?></tbody></table>
